let startDate = $fromAI("startDate", query, "string");
let endDate = $fromAI("endDate", "", "string");

console.log("startDate initial:", startDate);
console.log("endDate initial:", endDate);

function toISO8601(dateStr) {
  if (!dateStr) return null;
  const date = new Date(dateStr);
  if (isNaN(date.getTime())) {
    throw new Error(`Invalid date format: ${dateStr}`);
  }
  return date.toISOString();
}

if (!startDate) {
  startDate = new Date().toISOString().split('T')[0] + 'T00:00:00Z';
  console.log("startDate set to current date:", startDate);
} else {
  try {
    startDate = toISO8601(startDate);
    console.log("startDate converted:", startDate);
  } catch (e) {
    return `Error: Invalid startDate format - ${startDate}. Please use ISO 8601 (e.g., '2025-03-07T00:00:00Z').`;
  }
}

if (!endDate && startDate) {
  try {
    const start = new Date(startDate);
    console.log("start.getUTCDate():", start.getUTCDate());
    if (start.getUTCDate() === 1) {
      const lastDay = new Date(start);
      lastDay.setUTCMonth(lastDay.getUTCMonth() + 1);
      lastDay.setUTCDate(0);
      lastDay.setUTCHours(23, 59, 59, 999);
      endDate = lastDay.toISOString();
      console.log("endDate set to end of month:", endDate);
    } else {
      start.setUTCHours(23, 59, 59, 999);
      endDate = start.toISOString();
      console.log("endDate set to end of day:", endDate);
    }
  } catch (e) {
    return `Error: Failed to set endDate from startDate - ${startDate}.`;
  }
} else if (endDate) {
  try {
    endDate = toISO8601(endDate);
    console.log("endDate converted:", endDate);
  } catch (e) {
    return `Error: Invalid endDate format - ${endDate}. Please use ISO 8601 (e.g., '2025-03-07T23:59:59Z').`;
  }
}

let filter = `start/dateTime ge '${startDate}'`;
if (endDate) {
  filter += ` and end/dateTime le '${endDate}'`;
}

console.log("Final filter:", filter);
return filter;

// Предположим, что AI Agent возвращает строку JSON или уже объект
let outputObj;

try {
  // Если output - это строка JSON, преобразуем ее в объект
  if (typeof $json.output === 'string') {
    outputObj = JSON.parse($json.output);
  } else {
    // Если output уже является объектом
    outputObj = $json.output;
  }

  // Создаем объект результата со всеми извлеченными параметрами
  const result = {
    // Основная команда
    command: outputObj.command || "",

    // Параметры для контактов
    displayName: (outputObj.parameters?.displayName || "").trim().replace(/[^\w\sа-яА-Я]/g, ''),

    // Параметры для календаря
    startDate: outputObj.parameters?.startDate || "",
    endDate: outputObj.parameters?.endDate || "",
    eventTitle: outputObj.parameters?.eventTitle || "",
    eventID: outputObj.parameters?.eventID || "",

    // Параметры для почты
    emailAddress: outputObj.parameters?.emailAddress || "",
    subject: outputObj.parameters?.subject || "",
    emailBody: outputObj.parameters?.emailBody || "",
    ID: outputObj.parameters?.ID || "", // ID письма
    limit: outputObj.parameters?.limit || 10, // количество писем для получения

    // Параметры для обновления событий
    startTime: outputObj.parameters?.startTime || outputObj.parameters?.startDate || "",
    endTime: outputObj.parameters?.endTime || outputObj.parameters?.endDate || "",

    // Параметр для фильтрации событий календаря
    Filter_Query: outputObj.parameters?.Filter_Query || ""
  };

  return result;
} catch (error) {
  // В случае ошибок при парсинге, возвращаем объект с ошибкой
  return {
    error: true,
    message: `Ошибка обработки ответа AI Agent: ${error.message}`,
    originalOutput: $json.output
  };
}
